facts:
Differentiability fails at a corner, at a cusp, where the tangent is vertical, and wherever the function is discontinuous.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{scope}[shift={(0,0)}]
\draw[->] (-1.4,0) -- (1.5,0);
\draw[->] (0,-0.4) -- (0,1.7);
\draw[thick, domain=-1.15:0, variable=\x] plot ({\x},{-\x});
\draw[thick, domain=0:1.15, variable=\x] plot ({\x},{\x});
\fill (0,0) circle (2pt);
\node[below, font=\small] at (0,-0.75) {corner};
\end{scope}
\begin{scope}[shift={(3.6,0)}]
\draw[->] (-1.4,0) -- (1.5,0);
\draw[->] (0,-0.4) -- (0,1.7);
\draw[thick, smooth, samples=60, domain=-1.15:0, variable=\x] plot ({\x},{1.05*sqrt(abs(\x))});
\draw[thick, smooth, samples=60, domain=0:1.15, variable=\x] plot ({\x},{1.05*sqrt(abs(\x))});
\fill (0,0) circle (2pt);
\node[below, font=\small] at (0,-0.75) {cusp};
\end{scope}
\begin{scope}[shift={(0,-3.1)}]
\draw[->] (-1.4,0) -- (1.5,0);
\draw[->] (0,-0.4) -- (0,1.7);
\draw[thick, smooth, samples=60, domain=0:1.3, variable=\x] plot ({\x},{1.3*sqrt(\x)});
\fill (0,0) circle (2pt);
\node[below, font=\small] at (0,-0.75) {vertical tangent};
\end{scope}
\begin{scope}[shift={(3.6,-3.1)}]
\draw[->] (-1.4,0) -- (1.5,0);
\draw[->] (0,-0.4) -- (0,1.7);
\draw[thick] (-1.15,0.3) -- (0,1.15);
\fill (0,1.15) circle (2pt);
\draw[thick] (0,0.35) -- (1.15,0.75);
\draw[fill=white] (0,0.35) circle (2pt);
\node[below, font=\small] at (0,-0.75) {break};
\end{scope}
\end{tikzpicture}
[/tikz]

